DO $$ BEGIN CREATE TYPE public.app_role AS ENUM ('admin','client','clipper'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.campaign_status AS ENUM ('draft','open','paused','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.clip_platform AS ENUM ('tiktok','instagram','youtube','x','other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.submission_status AS ENUM ('submitted','approved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL, title text NOT NULL, brief text NOT NULL, platform public.clip_platform NOT NULL, reference_url text, reward_rate numeric, reward_description text NOT NULL DEFAULT '', target_views integer, status public.campaign_status NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.campaigns TO authenticated; GRANT ALL ON public.campaigns TO service_role;
ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.campaigns(id), clipper_id uuid NOT NULL, clip_url text NOT NULL, note text, status public.submission_status NOT NULL DEFAULT 'submitted', reported_views integer, proposed_reward numeric, review_note text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.submissions TO authenticated; GRANT ALL ON public.submissions TO service_role;
ALTER TABLE public.submissions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles,public.user_roles,public.campaigns,public.submissions FROM anon;
REVOKE INSERT,DELETE ON public.profiles FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.user_roles FROM authenticated;
REVOKE DELETE ON public.submissions FROM authenticated;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT _user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE r text := coalesce(new.raw_user_meta_data->>'role','clipper'); BEGIN IF r NOT IN ('client','clipper') THEN r:='clipper'; END IF; INSERT INTO public.profiles(id,display_name) VALUES(new.id,left(trim(coalesce(new.raw_user_meta_data->>'display_name','')),60)); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,r::public.app_role); RETURN new; END $$;
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tgname FROM pg_trigger WHERE tgrelid='auth.users'::regclass AND tgfoid='public.handle_new_user()'::regprocedure LOOP EXECUTE format('DROP TRIGGER %I ON auth.users',t.tgname); END LOOP; END $$;
CREATE TRIGGER clippza_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
DO $$ DECLARE p record; BEGIN FOR p IN SELECT tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('profiles','user_roles','campaigns','submissions') LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename); END LOOP; END $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY campaigns_read ON public.campaigns FOR SELECT TO authenticated USING(client_id=auth.uid() OR status='open' OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.submissions s WHERE s.campaign_id=campaigns.id AND s.clipper_id=auth.uid()));
CREATE POLICY campaigns_insert ON public.campaigns FOR INSERT TO authenticated WITH CHECK(client_id=auth.uid() AND public.has_role(auth.uid(),'client'));
CREATE POLICY campaigns_update ON public.campaigns FOR UPDATE TO authenticated USING(client_id=auth.uid() AND public.has_role(auth.uid(),'client')) WITH CHECK(client_id=auth.uid());
CREATE POLICY campaigns_delete ON public.campaigns FOR DELETE TO authenticated USING(client_id=auth.uid() AND public.has_role(auth.uid(),'client'));
CREATE OR REPLACE FUNCTION public.owns_campaign(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.campaigns WHERE id=_id AND client_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.owns_campaign(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owns_campaign(uuid) TO authenticated;
CREATE POLICY submissions_read ON public.submissions FOR SELECT TO authenticated USING(clipper_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.owns_campaign(campaign_id));
CREATE POLICY submissions_insert ON public.submissions FOR INSERT TO authenticated WITH CHECK(clipper_id=auth.uid() AND public.has_role(auth.uid(),'clipper') AND EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND c.status='open'));
CREATE POLICY submissions_review ON public.submissions FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.touch_campaign() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF new.id IS DISTINCT FROM old.id OR new.client_id IS DISTINCT FROM old.client_id OR new.created_at IS DISTINCT FROM old.created_at THEN RAISE EXCEPTION 'Campaign ownership and identity are immutable'; END IF; new.updated_at:=now(); RETURN new; END $$;
DROP TRIGGER IF EXISTS clippza_campaign_guard ON public.campaigns;
CREATE TRIGGER clippza_campaign_guard BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION public.touch_campaign();
CREATE OR REPLACE FUNCTION public.guard_submission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF tg_op='INSERT' THEN IF new.status<>'submitted' OR new.reported_views IS NOT NULL OR new.proposed_reward IS NOT NULL OR new.review_note IS NOT NULL OR new.reviewed_by IS NOT NULL OR new.reviewed_at IS NOT NULL THEN RAISE EXCEPTION 'Review fields are admin-only'; END IF; new.created_at:=now(); ELSE IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin review required'; END IF; IF new.id IS DISTINCT FROM old.id OR new.campaign_id IS DISTINCT FROM old.campaign_id OR new.clipper_id IS DISTINCT FROM old.clipper_id OR new.clip_url IS DISTINCT FROM old.clip_url OR new.note IS DISTINCT FROM old.note OR new.created_at IS DISTINCT FROM old.created_at THEN RAISE EXCEPTION 'Submission ownership and content are immutable'; END IF; IF new.status='submitted' OR nullif(trim(new.review_note),'') IS NULL THEN RAISE EXCEPTION 'A decision and review note are required'; END IF; new.reviewed_by:=auth.uid(); new.reviewed_at:=now(); END IF; RETURN new; END $$;
DROP TRIGGER IF EXISTS clippza_submission_guard ON public.submissions;
CREATE TRIGGER clippza_submission_guard BEFORE INSERT OR UPDATE ON public.submissions FOR EACH ROW EXECUTE FUNCTION public.guard_submission();
ALTER TABLE public.campaigns DROP CONSTRAINT IF EXISTS clippza_campaign_values;
ALTER TABLE public.campaigns ADD CONSTRAINT clippza_campaign_values CHECK(length(trim(title)) BETWEEN 3 AND 120 AND length(trim(brief)) BETWEEN 10 AND 4000 AND (reward_rate IS NULL OR reward_rate>=0) AND (target_views IS NULL OR target_views>0) AND length(reward_description)<=500 AND (reference_url IS NULL OR reference_url ~* '^https?://[^[:space:]]+'));
ALTER TABLE public.submissions DROP CONSTRAINT IF EXISTS clippza_submission_values;
ALTER TABLE public.submissions ADD CONSTRAINT clippza_submission_values CHECK(clip_url ~* '^https?://[^[:space:]]+' AND length(clip_url)<=500 AND length(coalesce(note,''))<=1000 AND length(coalesce(review_note,''))<=1000 AND (reported_views IS NULL OR reported_views>=0) AND (proposed_reward IS NULL OR proposed_reward>=0));
CREATE INDEX IF NOT EXISTS campaigns_client_idx ON public.campaigns(client_id);
CREATE INDEX IF NOT EXISTS campaigns_status_idx ON public.campaigns(status);
CREATE INDEX IF NOT EXISTS submissions_campaign_idx ON public.submissions(campaign_id);
CREATE INDEX IF NOT EXISTS submissions_clipper_idx ON public.submissions(clipper_id);
CREATE INDEX IF NOT EXISTS submissions_status_idx ON public.submissions(status);
REVOKE ALL ON FUNCTION public.handle_new_user(),public.guard_submission(),public.touch_campaign() FROM PUBLIC,anon,authenticated;